css:
/* Тема/переменные */
:root{
  --bg:#2e2e2e; --bg-alt:#343434; --fg:#f0f0f0; --dim:#cfcfcf; --accent:#FFC107; --border:#555;
  /* базовый размер текста грида и заголовков; 16–34px адаптивно */
  --grid-size: clamp(16px, 2.4vw, 34px);
  --line: 1.5; --gap:18px;
}

/* База */
.card{
  font-family:"Segoe UI","Helvetica Neue",Arial,sans-serif;
  background:var(--bg); color:var(--fg);
  margin:0; padding:0;
}

/* Контейнер бэка */
.card-wrap{
  height:100vh;
  box-sizing:border-box;
  display:flex; flex-direction:column;
  padding:0 2vw 2vh;
}

/* Шапка на 10% сверху */
.card-header{
  margin-top:1%;
  margin-bottom:.75rem;
  text-align:center;
  font-weight:600;
  font-size:var(--grid-size);
  line-height:var(--line);
  overflow-wrap:anywhere;
}

/* Две колонки (grid) */
.examples-grid{
  display:grid;
  grid-template-columns:minmax(0,1fr) minmax(0,1fr);
  gap:var(--gap);
  flex:1;           /* занять оставшееся место */
  min-height:0;     /* важно для корректной прокрутки детей */
}

/* Колонка */
.col{
  background:var(--bg-alt);
  border-left:2px solid var(--border);
  box-sizing:border-box;
  padding:14px 16px;
  min-width:0;
  overflow:auto;    /* длинный контент прокручивается внутри */
  border-radius:8px;
}

/* Заголовок секции = размеру текста в колонке */
.section-title{
  font-size:var(--grid-size);
  font-weight:600;
  color:var(--accent);
  margin:0 0 .5rem 0;
  padding-bottom:.25rem;
  border-bottom:1px solid var(--border);
}

/* Текст внутри колонок */
.grid-text{
  font-size:var(--grid-size);
  line-height:var(--line);
  color:var(--fg);
  overflow-wrap:anywhere;
}
.grid-text p,.grid-text li{ margin:.5rem 0; }
.grid-text p:not(:last-child),.grid-text li:not(:last-child){
  border-bottom:1px solid #444; padding-bottom:.5rem;
}

/* Мобильная адаптация */
@media (max-width:700px){
  .card-header{ margin-top:6%; }
  .examples-grid{ grid-template-columns:1fr; }
  .col{ border-left:0; }
}

/* ===== FRONT ONLY ===== */
.card.front{
  display:flex;
  align-items:center;     /* вертикально по центру */
  justify-content:center; /* горизонтально по центру */
  height:10vh;
  text-align:center;
  padding:0 4vw;          /* небольшой горизонтальный «буфер» */
}

.card.front .prompt{
  font-size: clamp(3rem, 14vw, 18rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: .02em;
  overflow-wrap:anywhere;
  color: #cfcfcf;   /* ← более тусклый вместо белого */
}

.card.front .prompt{
  /* крупный, адаптивный размер без px */
  font-size: clamp(3rem, 14vw, 18rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: .02em;
  overflow-wrap:anywhere; /* безопасные переносы */
}

.card.frontOnback{
  display: flex;
  align-items: center;      /* вертикальный центр */
  justify-content: center;  /* горизонтальный центр */
  height: 10vh;
  text-align: center;
  padding: 0 1vw;
  font-size: 3em;
}


/* ===== FRONT UI ===== */
.card.front{
  display:flex;
  align-items:center;
  justify-content:center;
  height:100vh;
  text-align:center;
  padding:0 4vw;
}

.card.front .prompt{
  font-size: clamp(2rem, 1vw, 18rem);
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: .02em;
  overflow-wrap:anywhere;
  color: #cfcfcf;
}

.card.front .front-ui{
  display:flex;
  flex-direction:column;
  align-items:center;
  gap: 12px;
}

/* строка ввода + индикатор */
.card.front .answer-row{
  display:flex;
  align-items:center;
  gap:10px;
  width:min(72vw, 760px);
  margin-top: 8px;
}

.card.front #answerInput{
  flex:1 1 auto;
  font-size: clamp(18px, 2.2vw, 28px);
  line-height: 1.3;
  padding: 12px 14px;
  color: var(--fg);
  background: #2f2f36;
  border: 2px solid rgba(124, 77, 255, .45); /* фиолетовый оттенок */
  border-radius: 12px;
  outline: none;
  transition: border-color .15s ease, box-shadow .15s ease, background .15s ease;
}
.card.front #answerInput::placeholder{ color:#9a9aa3; }
.card.front #answerInput:hover{ border-color: rgba(124,77,255,.65); }
.card.front #answerInput:focus{
  border-color: rgba(124,77,255,.95);
  box-shadow: 0 0 0 4px rgba(124,77,255,.18);
  background:#303038;
}

/* индикатор результата */
.card.front .result-icon{
  width: 36px; height: 36px;
  min-width:36px;
  border-radius: 10px;
  display:inline-flex;
  align-items:center;
  justify-content:center;
  font-size: 22px;
  font-weight: 800;
  background:#3a3a3a;
  color:#9a9a9a;
  border:1px solid #4a4a4a;
}
.card.front .result-icon.ok{
  background:#223f2a; color:#6BEB8B; border-color:#2f6a3c;
}
.card.front .result-icon.ok::before{ content: "✓"; }
.card.front .result-icon.bad{
  background:#432425; color:#ff8a80; border-color:#6b3a3e;
}
.card.front .result-icon.bad::before{ content: "✕"; }

/* панель подсказки */
.card.front .helpers{
  display:flex;
  align-items:center;
  gap:12px;
  margin-top: 2px;
}
.card.front .hint-btn{
  font-size: 14px;
  padding: 8px 12px;
  border-radius: 10px;
  background: #3a3555;
  color: #e6e0ff;
  border: 1px solid rgba(124,77,255,.4);
  cursor: pointer;
  transition: transform .05s ease, background .15s ease, border-color .15s ease;
}
.card.front .hint-btn:hover{
  background:#4a4380;
  border-color: rgba(124,77,255,.8);
}
.card.front .hint-btn:active{ transform: translateY(1px); }

.card.front .hint-letter{
  font-size: 14px;
  color: #cfcfcf;
  padding: 4px 8px;
  border-radius: 8px;
  background: #2f2f36;
  border: 1px solid #464656;
}
